<div class="page-actions"><div><p class="mb-0">Invoice, partial/full payment, overdue tracking, dan accounts receivable aging.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#invoiceCreateModal">New Invoice</button></div>
<div class="kpi-grid mb-3"><div class="kpi-card"><div><small>Outstanding</small><strong><?= e(money($kpi['outstanding'])) ?></strong></div></div><div class="kpi-card"><div><small>Due Today</small><strong><?= e(money($kpi['due_today'])) ?></strong></div></div><div class="kpi-card"><div><small>Overdue</small><strong><?= e(money($kpi['overdue'])) ?></strong></div></div><div class="kpi-card"><div><small>Paid This Month</small><strong><?= e(money($kpi['paid_month'])) ?></strong></div></div></div>
<div class="row g-3 mb-3"><div class="col-lg-8"><div class="card-panel"><div class="table-responsive"><table class="table datatable"><thead><tr><th>Invoice</th><th>Customer</th><th>Due</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><a href="<?= url('/invoices/'.$i['id']) ?>"><strong><?= e($i['invoice_number']) ?></strong></a></td><td><?= e($i['customer_name']) ?></td><td><?= e($i['due_date']??'-') ?></td><td><?= e(money($i['total'])) ?></td><td><?= e(money($i['paid'])) ?></td><td><?= e(money($i['balance'])) ?></td><td><span class="status-badge <?= $i['status']==='Paid'?'success':($i['status']==='Overdue'?'danger':'') ?>"><?= e($i['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="col-lg-4"><div class="card-panel"><h3 class="h6">AR Aging</h3><?php foreach(['0-30 days'=>'a0_30','31-60 days'=>'a31_60','61-90 days'=>'a61_90','>90 days'=>'a90plus'] as $label=>$key): ?><div class="aging-row"><span><?= e($label) ?></span><strong><?= e(money((float)($aging[$key]??0))) ?></strong></div><?php endforeach; ?></div></div></div>
<?php if(!empty($paymentProofs)): ?><div class="card-panel mb-3"><div class="panel-head"><div><h3>Pending Customer Payment Proofs</h3><p>Verify before the invoice balance is updated.</p></div><span class="status-badge"><?= count($paymentProofs) ?> pending</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th>Method</th><th>Reference</th><th class="text-end">Amount</th><th></th></tr></thead><tbody><?php foreach($paymentProofs as $p): ?><tr><td><?= e($p['invoice_number']) ?></td><td><?= e($p['customer_name']) ?></td><td><?= e($p['payment_date']) ?></td><td><?= e($p['payment_method']) ?></td><td><?= e($p['reference']??'-') ?></td><td class="text-end"><?= e(money($p['amount'])) ?></td><td class="text-end"><button class="btn btn-sm btn-success ajax-action" data-url="<?= url('/payment-proofs/'.$p['id'].'/review') ?>" data-payload='{"action":"approve"}'>Approve</button> <button class="btn btn-sm btn-outline-danger ajax-action" data-url="<?= url('/payment-proofs/'.$p['id'].'/review') ?>" data-payload='{"action":"reject"}'>Reject</button></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<div class="modal fade" id="invoiceCreateModal"><div class="modal-dialog modal-xl"><form class="modal-content ajax-form" method="post" action="<?= url('/invoices') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Invoice</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label">Customer</label><select class="form-select" name="customer_id" required><option value="">Select</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Due Date</label><input class="form-control" type="date" name="due_date" value="<?= date('Y-m-d',strtotime('+14 days')) ?>"></div></div><table class="table"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Price</th><th>Discount</th><th>Tax</th><th></th></tr></thead><tbody id="invoiceItems"></tbody></table><button type="button" class="btn btn-sm btn-outline-primary" data-add-row="invoice">Add Item</button></div><div class="modal-footer"><button class="btn btn-primary">Create Invoice</button></div></form></div></div>
